<template><div class="login-page"><div class="login-card"><h2>辅导员登录</h2><el-form :model="form" :rules="rules" ref="formRef"><el-form-item prop="username"><el-input v-model="form.username" placeholder="用户名" prefix-icon="User"/></el-form-item><el-form-item prop="password"><el-input v-model="form.password" type="password" placeholder="密码" prefix-icon="Lock" show-password/></el-form-item><el-form-item><el-button type="primary" @click="login" :loading="loading" style="width:100%">登录</el-button></el-form-item></el-form><div class="links"><router-link to="/register">还没有账号？立即注册</router-link></div><div class="admin-link"><router-link to="/admin/login">管理员登录</router-link></div></div></div></template>
<script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../../stores/auth';import api from'../../utils/request';import{ElMessage}from'element-plus';const router=useRouter(),auth=useAuthStore(),formRef=ref(),loading=ref(false),form=reactive({username:'',password:''}),rules={username:[{required:true,message:'请输入用户名'}],password:[{required:true,message:'请输入密码'}]};async function login(){if(!await formRef.value.validate().catch(()=>false))return;loading.value=true;try{const{data}=await api.post('/auth/counselor/login',form);auth.setCounselor(data);ElMessage.success('登录成功');router.push(data.mustChangePassword?'/profile?tab=password':'/')}finally{loading.value=false}}</script>
<style scoped>.login-page{height:100vh;display:flex;align-items:center;justify-content:center;background:#edf2f7}.login-card{width:380px;padding:40px;background:#fff;border-radius:8px;box-shadow:0 4px 24px rgba(0,0,0,.15)}.login-card h2{text-align:center;margin-bottom:24px}.links,.admin-link{text-align:center;margin-top:12px}.admin-link{font-size:13px}@media(max-width:460px){.login-card{width:calc(100% - 32px);padding:30px 22px}}</style>
